import { supabase } from "@/integrations/supabase/client";
import { trackEvent } from "@/lib/analytics";
import type { CardTheme } from "@/components/challenge-tools/ToolDocuments";

// Client side of the free challenge tools. The professional business card is generated by the
// challenge-tool-generate edge function and stored in therapist_deliverables (tool = 'professional-card'); what the
// therapist chooses and edits afterwards (the version, the wording, the colour, the card details) is saved on the
// same row as edited_content, which the owner may update.

export type Gender = "f" | "m" | "n";
export type Person = "f" | "m";
export type CardToolKey = "professional-card";

export interface CardVariant {
  tag: string;
  lead: string;
  who: string;
  change: string;
}

export interface CardContent {
  gender: Gender;
  person: Person;
  niche_line: string;
  person_summary: string;
  variants: CardVariant[];
}

export interface CardEdit {
  variant: number;
  sentence: string | null; // the therapist's own wording, replacing the whole sentence
  theme: CardTheme;
  name: string;
  title: string;
  phone: string;
  site: string;
}

export interface CardRow {
  id: string;
  version: number;
  content: CardContent;
  edited_content: CardEdit | null;
  inputs: { answers?: string[]; gender?: Gender; person?: Person; source?: string | null };
  created_at: string;
}

export type GenerateCardResult =
  | { status: "ok"; row: CardRow }
  | { status: "needs_info"; missing: { index: number; hint: string }[] }
  | { status: "failed" }
  | { status: "limit" }
  | { status: "error" };

const SRC_KEY = "challenge_tool_src";
const cleanSrc = (v: string | null) => (v ?? "").trim().toLowerCase().replace(/[^a-z0-9_.:-]/g, "").slice(0, 60);

// Which homework link brought the therapist here (?src=hw1). Kept for the browser session so it survives the
// detour through sign-up.
export function rememberSource(search: string): string | null {
  const fromUrl = cleanSrc(new URLSearchParams(search).get("src"));
  try {
    if (fromUrl) sessionStorage.setItem(SRC_KEY, fromUrl);
    return fromUrl || sessionStorage.getItem(SRC_KEY);
  } catch {
    return fromUrl || null;
  }
}

export async function generateCard(input: { answers: string[]; gender: Gender; person: Person; source: string | null }): Promise<GenerateCardResult> {
  const { data, error } = await supabase.functions.invoke("challenge-tool-generate", { body: { tool: "professional-card", ...input } });
  if (error) {
    const status = (error as { context?: Response }).context?.status;
    return { status: status === 429 ? "limit" : "error" };
  }
  if (data?.status === "ok") {
    const d = data.deliverable;
    return {
      status: "ok",
      row: { id: d.id, version: d.version, content: d.content, edited_content: null, inputs: { ...input, answers: input.answers }, created_at: new Date().toISOString() },
    };
  }
  if (data?.status === "needs_info") return { status: "needs_info", missing: data.missing ?? [] };
  return { status: "failed" };
}

export async function loadLatestCard(): Promise<CardRow | null> {
  const { data, error } = await supabase
    .from("therapist_deliverables")
    .select("id, version, content, edited_content, inputs, created_at")
    .eq("tool", "professional-card")
    .order("version", { ascending: false })
    .limit(1);
  if (error) throw error;
  const row = (data ?? [])[0];
  return row ? (row as unknown as CardRow) : null;
}

export async function saveCardEdit(id: string, edit: CardEdit): Promise<void> {
  const { error } = await supabase
    .from("therapist_deliverables")
    .update({ edited_content: edit as unknown as never, updated_at: new Date().toISOString() })
    .eq("id", id);
  if (error) throw error;
}

// Viewing, editing, downloading and starting over show whether the tool is used (and feed the admin analytics).
export async function recordCardEvent(kind: "viewed" | "downloaded" | "edited" | "regenerated", deliverableId: string | null, extra: Record<string, string> = {}) {
  trackEvent(`challenge_card_${kind}`, extra);
  try {
    const { data } = await supabase.auth.getUser();
    if (!data.user) return;
    await supabase.from("deliverable_events").insert({ user_id: data.user.id, deliverable_id: deliverableId, tool: "professional-card", kind });
  } catch (e) {
    console.error("failed to record challenge card event", e);
  }
}
